import socket, time, sys

HOST, PORT = "crypto.chal.csaw.io", 21004

class Oracle:
    def __init__(self):
        self.s = socket.create_connection((HOST, PORT), timeout=30)
        self.s.settimeout(30)
        self.buf = b""
        self.count = 0
        self._read_banner()

    def _read_banner(self):
        while b"> " not in self.buf:
            d = self.s.recv(4096)
            if not d:
                raise EOFError("closed at banner")
            self.buf += d
        self.buf = b""

    def query(self, hexmsg):
        self.count += 1
        self.s.sendall(hexmsg.encode() + b"\n")
        deadline = time.time() + 30
        while True:
            if b"Invalid communication." in self.buf:
                r = "invalid"
            elif b"No connection found." in self.buf:
                r = "valid"
            else:
                r = None
            if r:
                # consume up to and including the response line
                idx = max(self.buf.find(b"Invalid communication."), self.buf.find(b"No connection found."))
                end = self.buf.find(b"\n", idx)
                self.buf = self.buf[end+1:] if end != -1 else b""
                return r
            self.s.settimeout(max(0.1, deadline - time.time()))
            try:
                d = self.s.recv(4096)
            except socket.timeout:
                raise EOFError("timeout waiting for response")
            if not d:
                raise EOFError("closed: buf=%r" % self.buf[:200])
            self.buf += d

    def close(self):
        try:
            self.s.close()
        except Exception:
            pass

if __name__ == "__main__":
    D = open('/home/ctfplayer/ctf_files/dist/intercepted_transmission.txt').read().strip()
    o = Oracle()
    print("orig:", o.query(D))
    # flip last byte across all values, see which are 'valid'
    base = D[:-2]
    valid_vals = []
    for v in range(256):
        r = o.query(base + "%02x" % v)
        if r == "valid":
            valid_vals.append(v)
    print("last-byte values that validate:", valid_vals, "count:", len(valid_vals))
    print("queries used:", o.count)
    o.close()

